// app.js – hardened version
// -------------------------------------------------
// Simple application for the agent to work on.
// This file now includes baseline security hardening.

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// -------------------------------------------------
// 1️⃣ Trust proxy (important when behind load balancers)
// -------------------------------------------------
app.set('trust proxy', true);

// -------------------------------------------------
// 2️⃣ Security middlewares
// -------------------------------------------------
app.use(helmet()); // Sets a sensible set of security headers
app.use(cors({               // Adjust origins to your actual client domains
  origin: process.env.CORS_ORIGIN || 'https://my‑trusted‑domain.com',
  methods: ['GET'],
}));
app.use(
  rateLimit({
    windowMs: 60 * 1000, // 1 minute window
    max: 100,            // limit each IP to 100 requests per window
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// -------------------------------------------------
// 3️⃣ Basic health & demo users endpoint
// -------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Static demo data – replace with DB call in real app
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// -------------------------------------------------
// 4️⃣ Centralised error handling (no stack traces to client)
// -------------------------------------------------
app.use((err, _req, res, _next) => {
  // Log the error server‑side – replace with your logger
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// -------------------------------------------------
// 5️⃣ Server start (port from env, fallback to 3000)
// -------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// -------------------------------------------------
// Export for testing / downstream usage
// -------------------------------------------------
module.exports = app;
```

**What changed?**

* **Helmet** – adds CSP, HSTS, X‑Frame‑Options, etc.
* **CORS** – forces a whitelist (adjust to your environment).
* **Rate limiting** – mitigates brute‑force / DoS on public endpoints.
* **Trust proxy** – needed for correct handling of `X‑Forwarded‑Proto`.
* **Error handler** – hides stack traces from clients.
* **Port from env** – easier to run in containers/PAAS.
* **Comments** – guide future developers on why each piece exists.

