**app.js** – keep only route definitions & export the Express instance.

```js
// app.js
const express = require('express');
const router = express.Router();

/**
 * Health check – no auth required.
 */
router.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Users endpoint – protected. In a real service you’d replace this
 * with a DB lookup and proper auth checks.
 */
router.get('/users', (req, res) => {
  // Placeholder auth: require a static token for demo purposes.
  const authHeader = req.get('Authorization') || '';
  if (!authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // In production verify the token (JWT, session, API key, etc.).
  // For now we simply accept any Bearer token.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

module.exports = router;
```

### 3.2 Secure Server Bootstrap (`server.js`)

```js
// server.js
require('dotenv').config(); // Load env vars (if any)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// 1️⃣ Security middlewares
app.use(helmet());                           // Sets secure headers
app.use(cors({ origin: process.env.CORS_ORIGIN || false })); // Restrict origins
app.use(express.json({ limit: '100kb' }));   // Body‑parser size limit
app.use(morgan('combined'));                 // Request logging (avoid dev‑only console)

// 2️⃣ Rate limiting – 100 req/min per IP (adjust as needed)
const limiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3️⃣ Mount routes
const routes = require('./app');
app.use('/', routes);

// 4️⃣ Global error handler (does not leak stack traces in prod)
app.use((err, req, res, next) => {
  console.error(err); // Log internally
  const status = err.status || 500;
  const response = { error: status === 500 ? 'Internal Server Error' : err.message };
  res.status(status).json(response);
});

// 5️⃣ Enforce HTTPS in production (optional – depends on deployment)
if (process.env.NODE_ENV === 'production') {
  app.enable('trust proxy'); // Needed if behind a reverse proxy
  app.use((req, res, next) => {
    if (req.secure) return next();
    res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  });
}

// 6️⃣ Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on ${process.env.NODE_ENV === 'production' ? 'HTTPS' : 'HTTP'} port ${PORT}`);
});
```

**Why these changes help**

| Change | Mitigated Risk |
|--------|----------------|
| `helmet()` | Missing security headers (X‑XSS‑Protection, CSP, etc.) |
| `cors()` with explicit origin | Open‑origin API abuse |
| `express.json({ limit })` | Large‑payload DoS |
| `express-rate-limit` | Simple rate‑limiting to curb brute‑force / DoS |
| Auth check on `/users` (Bearer token placeholder) | Basic information‑disclosure mitigation |
| Global error handler | Prevents stack‑trace leakage |
| HTTPS redirect (production) | Forces encrypted transport |
| `morgan` logging | Auditable request logs (helps detect abuse) |
| `.env` loading via `dotenv` | Centralises secret handling; avoids hard‑coding in source |

