app.use(cors({ origin: false }));       // Disable CORS by default (adjust for your front‑end)
app.use(express.json({ limit: '10kb' })); // Body size limiter (good for future POST routes)

// -------------------------------------------------
// Logging (replace with winston/pino for production)
// -------------------------------------------------
