// HTTPS enforcement (only when behind a proxy)
// -------------------------------------------------
if (process.env.NODE_ENV === 'production') {
  // Express must trust the reverse proxy to see the X‑Forwarded‑Proto header
  app.set('trust proxy', 1);
  app.use((req, res, next) => {
    if (req.secure) {
      return next();
    }
    // Redirect HTTP → HTTPS
