## 3. Quick “hardening” patch

Below is a **minimal** set of changes that immediately addresses the most glaring gaps without redesigning the whole app. You can copy‑paste this into `app.js` (or create a new file that imports the original and augments it).

```js
// app.js – hardened version (minimal changes)
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// ---------- Security middleware ----------
app.use(helmet());                     // Sets a robust set of security headers
app.use(cors({                         // Restrict origins as needed
  origin: process.env.ALLOWED_ORIGIN   // e.g. "https://myfrontend.com"
    ? process.env.ALLOWED_ORIGIN.split(',')
    : '*',                             // default permissive for dev only
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
// Simple global rate‑limiter (adjust limits per environment)
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: process.env.NODE_ENV === 'production' ? 100 : 200, // lower in prod
  message: { error: 'Too many requests, please retry later.' },
});
app.use(limiter);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app this would be behind auth & would not return raw emails.
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ---------- Error handling ----------
app.use((err, _req, res, _next) => {
  // Log the error internally (could plug winston/morgan here)
  console.error(err);
  // Do not expose stack traces in production
  const msg = process.env.NODE_ENV === 'production'
    ? { error: 'Internal Server Error' }
    : { error: err.message, stack: err.stack };
  res.status(500).json(msg);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

**What this patch adds**

1. **Helmet** – adds `Content‑Security‑Policy`, `X‑Frame‑Options`, etc.
2. **CORS** – allows you to lock down origins (environment‑driven).
3. **Rate limiting** – mitigates brute‑force / DoS.
4. **Generic error handler** – prevents accidental stack‑trace leaks.
5. **Sanitized `/users` response** – removes email addresses (the privacy‑sensitive field). In production you’d also enforce authentication before even exposing the route.

