  const status = err.status || 500;
  const msg = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: msg });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
