## 3. Immediate remediation steps

Below is a minimal “secure by default” rewrite that you can drop into `app.js`. It keeps the existing functionality while adding the most common mitigations.

```js
// ----------- app.js – Hardened version --------------
const express = require('express');
const helmet = require('helmet');               // security headers
const rateLimit = require('express-rate-limit'); // basic DoS protection
const cors = require('cors');                  // optional CORS control
const morgan = require('morgan');               // structured request logging

const app = express();

// ---------- Middleware ----------
app.use(helmet());
// Example CSP – adjust as needed for your front‑end
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: [],
    },
  })
);

// Enable CORS only for trusted origins (replace with your domain)
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    methods: ['GET'],
  })
);

// Basic request logging (combined format works well with most log aggregators)
app.use(morgan('combined'));

// Rate limiting – 100 requests per 15 min per IP (tune to your traffic)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(apiLimiter);

// If you ever accept JSON bodies, enable the parser (currently unused)
// app.use(express.json());

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // Optional: restrict to internal IPs or a secret token
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // *** AUTHENTICATION required in real world ***
  // For demo purposes we still return static data but hide email addresses.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Mask emails (or remove the field) before sending publicly
  const safeUsers = users.map(u => ({
    id: u.id,
    name: u.name,
    // comment out next line if you really need to expose the email
    // email: u.email,
  }));

  res.json(safeUsers);
});

// ---------- Error handling ----------
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  // Log the error internally but don’t expose stack traces to the client
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------- Server ----------
const PORT = process.env.PORT || 3000;

// If you sit behind a reverse‑proxy that terminates TLS, enable trust‑proxy
if (process.env.NODE_ENV === 'production') {
  app.set('trust proxy', 1);
}
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What this adds

| Feature | Why it matters |
|---------|----------------|
| `helmet` | Sets a comprehensive set of security‑related HTTP headers (CSP, HSTS, X‑XSS‑Protection, etc.). |
| `express-rate-limit` | Thwarts brute‑force & basic DoS attacks by limiting request frequency per IP. |
| `cors` | Controls which origins can consume the API – you can lock it down to internal domains. |
| `morgan` | Structured request logs help you spot anomalies (e.g., massive request bursts). |
| Graceful 404/500 handlers | Prevents leaking stack traces and ensures the app always returns JSON. |
| Environment‑driven `PORT` & `trust proxy` | Makes the app flexible for production deployments (e.g., behind Nginx). |
| Email masking | Stops leaking personally‑identifiable information (PII) in the public `/users` endpoint. |
| Comment placeholders for future authentication | Reminds developers to protect routes that will eventually expose real data. |

